// Lab 3.9 needs findings that are real rather than staged. Inactive people
// still holding a licence is the most common one on any org older than a year.
List<User> stale = [SELECT Id, LastLoginDate FROM User WHERE IsActive = true AND Profile.UserLicense.Name = 'Salesforce' LIMIT 5];
System.debug('Users monitoring will look at: ' + stale.size());

// Lab 3.7 reads DORA metrics. They come from the git history, not from the
